arguments.new_str:
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Pages;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Components;
using ShipmentTracker.Components.Account;
using ShipmentTracker.Data;

var builder = WebApplication.CreateBuilder(args);

// Add services to the container.
builder.Services.AddRazorComponents()
    .AddInteractiveServerComponents()
    .AddInteractiveWebAssemblyComponents()
    .AddAuthenticationStateSerialization();

builder.Services.AddCascadingAuthenticationState();
builder.Services.AddScoped<IdentityRedirectManager>();
builder.Services.AddScoped<AuthenticationStateProvider, IdentityRevalidatingAuthenticationStateProvider>();

builder.Services.AddAuthentication(options =>
    {
        options.DefaultScheme = IdentityConstants.ApplicationScheme;
        options.DefaultSignInScheme = IdentityConstants.ExternalScheme;
    })
    .AddIdentityCookies();

var connectionString = builder.Configuration.GetConnectionString("DefaultConnection") ?? throw new InvalidOperationException("Connection string 'DefaultConnection' not found.");
builder.Services.AddDbContext<ApplicationDbContext>(options =>
    options.UseSqlite(connectionString));
builder.Services.AddDatabaseDeveloperPageExceptionFilter();

builder.Services.AddIdentityCore<ApplicationUser>(options =>
    {
        options.SignIn.RequireConfirmedAccount = true;
        options.Stores.SchemaVersion = IdentitySchemaVersions.Version3;
    })
    .AddEntityFrameworkStores<ApplicationDbContext>()
    .AddSignInManager()
    .AddDefaultTokenProviders();

builder.Services.AddSingleton<IEmailSender<ApplicationUser>, IdentityNoOpEmailSender>();

builder.Services.AddHttpClient<IShipmentService, HttpShipmentService>(client =>
{
    client.BaseAddress = new Uri("http://localhost:5000");
});
builder.Services.AddScoped<IShipmentService>(sp =>
{
    var factory = sp.GetRequiredService<IHttpClientFactory>();
    var client = factory.CreateClient(nameof(HttpShipmentService));
    return new HttpShipmentService(client);
});

var app = builder.Build();

// Migrate and seed database
using (var scope = app.Services.CreateScope())
{
    var db = scope.ServiceProvider.GetRequiredService<ApplicationDbContext>();
    db.Database.Migrate();

    if (!db.Shipments.Any())
    {
        db.Shipments.AddRange(
            new Shipment { TrackingNumber = "TRK-001", Origin = "New York, NY", Destination = "Los Angeles, CA", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.Now.AddDays(3), CustomerEmail = "alice@example.com", Description = "Electronics - Laptop", CreatedAt = DateTime.Now.AddDays(-2), LastUpdated = DateTime.Now },
            new Shipment { TrackingNumber = "TRK-002", Origin = "Chicago, IL", Destination = "Houston, TX", Status = ShipmentStatus.Pending, EstimatedDelivery = DateTime.Now.AddDays(5), CustomerEmail = "bob@example.com", Description = "Furniture - Office Chair", CreatedAt = DateTime.Now.AddDays(-1), LastUpdated = DateTime.Now },
            new Shipment { TrackingNumber = "TRK-003", Origin = "Seattle, WA", Destination = "Miami, FL", Status = ShipmentStatus.Delivered, EstimatedDelivery = DateTime.Now.AddDays(-1), CustomerEmail = "carol@example.com", Description = "Books - Textbooks", CreatedAt = DateTime.Now.AddDays(-7), LastUpdated = DateTime.Now.AddDays(-1) },
            new Shipment { TrackingNumber = "TRK-004", Origin = "Denver, CO", Destination = "Boston, MA", Status = ShipmentStatus.Delayed, EstimatedDelivery = DateTime.Now.AddDays(2), CustomerEmail = "dave@example.com", Description = "Clothing - Winter Jacket", CreatedAt = DateTime.Now.AddDays(-4), LastUpdated = DateTime.Now },
            new Shipment { TrackingNumber = "TRK-005", Origin = "Atlanta, GA", Destination = "Phoenix, AZ", Status = ShipmentStatus.InTransit, EstimatedDelivery = DateTime.Now.AddDays(4), CustomerEmail = "eve@example.com", Description = "Sports Equipment - Bicycle", CreatedAt = DateTime.Now.AddDays(-3), LastUpdated = DateTime.Now }
        );
        db.SaveChanges();
    }
}

// Configure the HTTP request pipeline.
if (app.Environment.IsDevelopment())
{
    app.UseWebAssemblyDebugging();
    app.UseMigrationsEndPoint();
}
else
{
    app.UseExceptionHandler("/Error", createScopeForErrors: true);
}
app.UseStatusCodePagesWithReExecute("/not-found", createScopeForStatusCodePages: true);
app.UseAntiforgery();

// Minimal API endpoints for shipments
app.MapGet("/api/shipments", async (ApplicationDbContext db) =>
{
    var shipments = await db.Shipments.ToListAsync();
    return shipments.Select(s => new ShipmentDto
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status,
        EstimatedDelivery = s.EstimatedDelivery,
        CustomerEmail = s.CustomerEmail,
        Description = s.Description,
        CreatedAt = s.CreatedAt,
        LastUpdated = s.LastUpdated
    }).ToList();
});

app.MapGet("/api/shipments/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
    if (shipment == null) return Results.NotFound();
    return Results.Ok(new ShipmentDto
    {
        Id = shipment.Id,
        TrackingNumber = shipment.TrackingNumber,
        Origin = shipment.Origin,
        Destination = shipment.Destination,
        Status = shipment.Status,
        EstimatedDelivery = shipment.EstimatedDelivery,
        CustomerEmail = shipment.CustomerEmail,
        Description = shipment.Description,
        CreatedAt = shipment.CreatedAt,
        LastUpdated = shipment.LastUpdated
    });
});

app.MapPut("/api/shipments/{id}/status", async (int id, StatusUpdateRequest request, ApplicationDbContext db) =>
{
    var shipment = await db.Shipments.FindAsync(id);
    if (shipment == null) return Results.NotFound();
    shipment.Status = request.Status;
    shipment.LastUpdated = DateTime.Now;
    await db.SaveChangesAsync();
    return Results.Ok();
});

app.MapStaticAssets();
app.MapRazorComponents<App>()
    .AddInteractiveServerRenderMode()
    .AddInteractiveWebAssemblyRenderMode()
    .AddAdditionalAssemblies(typeof(ShipmentTracker.Client._Imports).Assembly);

// Add additional endpoints required by the Identity /Account Razor components.
app.MapAdditionalIdentityEndpoints();

app.Run();

public record StatusUpdateRequest(ShipmentStatus Status);

